available_endpoints <- names(Filter(function(spec) !is.null(pick_endpoint_obj(spec$candidates)), endpoint_specs))
if (length(available_endpoints) == 0) {
  stop("No recognized SPINE-TRACT endpoint objects were found in model_bundle.rds.", call. = FALSE)
}

get_endpoint_obj <- function(endpoint) {
  spec <- endpoint_specs[[endpoint]]
  obj <- pick_endpoint_obj(spec$candidates)
  if (is.null(obj)) stop("Endpoint not found in model bundle: ", endpoint, call. = FALSE)
  obj
}

get_predictors <- function(endpoint, obj) {
  preds <- obj$predictors %||% obj$raw_predictors %||% NULL
  if (!is.null(preds) && length(preds) > 0) return(as.character(preds))

  if (endpoint == "mechanical_ventilation") {
    preds <- meta_obj$predictors_no_resp %||% meta_obj$predictors_full %||% NULL
  } else {
    preds <- meta_obj$predictors_full %||% NULL
  }
  if (!is.null(preds) && length(preds) > 0) return(as.character(preds))

  unique(metadata$variable)
}

get_feature_names <- function(obj, model) {
  fn <- obj$feature_names %||% model$feature_names %||% NULL
  if (!is.null(fn) && length(fn) > 0) return(as.character(fn))
  NULL
}

# ------------------------------------------------------------
# Input/default helpers
# ------------------------------------------------------------

split_choices <- function(x, fallback = character(0)) {
  if (is.null(x) || length(x) == 0 || is.na(x[1]) || !nzchar(as.character(x[1]))) return(fallback)
  out <- unlist(strsplit(as.character(x[1]), "\\|\\|"))
  out <- out[!is.na(out) & nzchar(out)]
  if (length(out) == 0) fallback else out
}

first_or <- function(x, fallback) {
  x <- x[!is.na(x) & nzchar(as.character(x))]
  if (length(x) == 0) fallback else as.character(x[1])
}

safe_numeric <- function(x, default = 0) {
  if (is.null(x) || length(x) == 0) return(default)
  y <- suppressWarnings(as.numeric(x[[1]]))
  if (!is.finite(y)) return(default)
  y
}

safe_int01 <- function(x) {
  if (is.null(x) || length(x) == 0) return(0L)
  as.integer(as.character(x[[1]]) %in% c("1", "Yes", "yes", "TRUE", "true", TRUE))
}

input_id <- function(v) paste0("var__", v)

is_yesno_var <- function(row) {
  choices <- split_choices(row$choices, character(0))
  identical(sort(choices), c("0", "1")) ||
    tolower(row$input_type) %in% c("yesno", "checkbox", "binary") ||
    grepl("^(dx_|ais_|has_|any_)", row$variable) ||
    row$variable %in% c("bleeding_disorder", "diabetes", "copd", "hypertension", "current_smoker")
}

is_numeric_var <- function(row) {
  tolower(row$input_type) %in% c("numeric", "integer", "continuous", "gcs_select", "ais_severity") ||
    grepl("age|gcs|sbp|pulse|rr|spo2|count|burden|score|number|n_", row$variable, ignore.case = TRUE)
}

default_for <- function(v) {
  row <- metadata[variable == v][1]
  if (nrow(row) == 0) return(0)

  choices <- split_choices(row$choices, character(0))
  def <- as.character(row$default)
  if (is.na(def) || !nzchar(def)) def <- NA_character_

  if (is_yesno_var(row)) return(first_or(def, "0"))
  if (length(choices) > 0) return(first_or(def[def %in% choices], choices[1]))
  if (is_numeric_var(row)) return(safe_numeric(def, 0))
  first_or(def, "0")
}

visible_vars <- metadata[
  !tolower(input_type) %in% c("derived", "hidden", "none") &
    !grepl("_aug$|^n_|count|burden", variable, ignore.case = TRUE),
  variable
]

# Ensure likely clinically important variables are shown even if metadata is sparse.
visible_vars <- unique(c(
  intersect(c(
    "age", "sex_clean", "race_clean", "ethnicity_clean", "insurance_clean",
    "transfer_clean", "mechanism_clean",
    "gcs_eye_clean", "gcs_motor_clean", "gcs_verbal_clean", "gcs_total_aug", "pupil_clean",
    "sbp_clean", "pulse_clean", "rr_clean", "spo2_clean", "respiratoryassistance_clean",
    "bleeding_disorder", "diabetes", "copd", "hypertension", "current_smoker"
  ), metadata$variable),
  visible_vars
))

metadata[, is_visible_app := variable %in% visible_vars]

make_input <- function(row) {
  v <- row$variable
  label <- row$label
  id <- input_id(v)
  choices <- split_choices(row$choices, character(0))
  def <- default_for(v)

  if (is_yesno_var(row)) {
    return(selectInput(id, label, choices = c("No" = "0", "Yes" = "1"), selected = as.character(def)))
  }

  if (length(choices) > 0 && !is_numeric_var(row)) {
    return(selectInput(id, label, choices = stats::setNames(choices, choices), selected = as.character(def)))
  }

  min_val <- suppressWarnings(as.numeric(row$min))
  max_val <- suppressWarnings(as.numeric(row$max))
  if (!is.finite(min_val)) min_val <- NA_real_
  if (!is.finite(max_val)) max_val <- NA_real_

  numericInput(
    id,
    label,
    value = safe_numeric(def, 0),
    min = min_val,
    max = max_val,
    step = if (grepl("age|gcs|count|score|burden", v, ignore.case = TRUE)) 1 else NA
  )
}

# ------------------------------------------------------------
# Derived values
# ------------------------------------------------------------

get_val <- function(row, v) row[[v]] %||% default_for(v)
get_yesno <- function(row, v) safe_int01(row[[v]] %||% default_for(v))

pick_choice <- function(v, pattern, fallback = NULL) {
  row <- metadata[variable == v][1]
  choices <- split_choices(row$choices, character(0))
  if (length(choices) == 0) return(fallback %||% 0)
  hit <- choices[grepl(pattern, choices, ignore.case = TRUE)][1]
  if (is.na(hit)) choices[1] else hit
}

derive_age_group <- function(age, v) {
  choices <- split_choices(metadata[variable == v][1]$choices, character(0))
  if (length(choices) == 0) return(default_for(v))
  age <- safe_numeric(age, NA_real_)
  if (!is.finite(age)) return(default_for(v))
  if (age < 40) return(first_or(choices[grepl("18|39|young", choices, ignore.case = TRUE)], choices[1]))
  if (age < 65) return(first_or(choices[grepl("40|64|adult", choices, ignore.case = TRUE)], choices[1]))
  if (age < 75) return(first_or(choices[grepl("65|74", choices, ignore.case = TRUE)], choices[1]))
  first_or(choices[grepl("75|80|older|elder", choices, ignore.case = TRUE)], choices[length(choices)])
}

derive_gcs_severity <- function(gcs, v) {
  choices <- split_choices(metadata[variable == v][1]$choices, character(0))
  if (length(choices) == 0) return(default_for(v))
  gcs <- safe_numeric(gcs, NA_real_)
  if (!is.finite(gcs)) return(default_for(v))
  if (gcs >= 13) return(first_or(choices[grepl("mild|13", choices, ignore.case = TRUE)], choices[1]))
  if (gcs >= 9) return(first_or(choices[grepl("moderate|9", choices, ignore.case = TRUE)], choices[1]))
  first_or(choices[grepl("severe|3", choices, ignore.case = TRUE)], choices[1])
}

build_patient_row <- function(input) {
  vars <- unique(metadata$variable)
  row <- as.list(stats::setNames(lapply(vars, default_for), vars))

  for (v in visible_vars) {
    id <- input_id(v)
    if (!is.null(input[[id]])) row[[v]] <- input[[id]]
  }

  # Standard derived variables used in the modeling pipeline.
  if ("age_group_aug" %in% vars) row$age_group_aug <- derive_age_group(row$age, "age_group_aug")
  if ("gcs_severity_aug" %in% vars) row$gcs_severity_aug <- derive_gcs_severity(row$gcs_total_aug, "gcs_severity_aug")
  if ("hypotension_sbp90_aug" %in% vars) row$hypotension_sbp90_aug <- as.integer(safe_numeric(row$sbp_clean, 999) < 90)
  if ("hypoxia_spo2_90_aug" %in% vars) row$hypoxia_spo2_90_aug <- as.integer(safe_numeric(row$spo2_clean, 999) <= 90)
  if ("tachycardia_120_aug" %in% vars) row$tachycardia_120_aug <- as.integer(safe_numeric(row$pulse_clean, 0) >= 120)
  if ("abnormal_rr_aug" %in% vars) {
    rr <- safe_numeric(row$rr_clean, 16)
    row$abnormal_rr_aug <- as.integer(rr < 10 | rr > 29)
  }

  if ("n_preexisting_conditions" %in% vars) {
    comorb <- c("bleeding_disorder", "diabetes", "copd", "hypertension", "current_smoker")
    row$n_preexisting_conditions <- sum(vapply(comorb[comorb %in% vars], function(v) get_yesno(row, v), numeric(1)), na.rm = TRUE)
  }

  # Common thoracolumbar phenotype aggregations. If names differ, the metadata default is retained.
  thoracic_fx <- get_yesno(row, "dx_thoracic_vertebral_fracture")
  lumbar_fx <- get_yesno(row, "dx_lumbar_vertebral_fracture")
  sci <- max(get_yesno(row, "dx_tl_spinal_cord_injury"), get_yesno(row, "dx_thoracolumbar_spinal_cord_injury"), na.rm = TRUE)
  cauda <- max(get_yesno(row, "dx_cauda_equina_or_nerve_root"), get_yesno(row, "dx_cauda_equina_injury"), get_yesno(row, "dx_nerve_root_injury"), na.rm = TRUE)
  neural_any <- as.integer(sci == 1L || cauda == 1L)

  if ("dx_both_tl_fracture_levels" %in% vars) row$dx_both_tl_fracture_levels <- as.integer(thoracic_fx == 1L && lumbar_fx == 1L)
  if ("dx_tl_neural_injury" %in% vars) row$dx_tl_neural_injury <- neural_any
  if ("dx_fracture_with_tl_neural_injury" %in% vars) row$dx_fracture_with_tl_neural_injury <- as.integer((thoracic_fx == 1L || lumbar_fx == 1L) && neural_any == 1L)

  # Generic count/polyregion helpers for models that use ICD-derived burden variables.
  dx_vars <- vars[grepl("^dx_", vars)]
  visible_dx <- dx_vars[dx_vars %in% visible_vars]
  if ("n_unique_icd_dx_codes" %in% vars) row$n_unique_icd_dx_codes <- sum(vapply(visible_dx, function(v) get_yesno(row, v), numeric(1)), na.rm = TRUE)
  if ("n_traumatic_icd_dx_codes" %in% vars) row$n_traumatic_icd_dx_codes <- sum(vapply(visible_dx, function(v) get_yesno(row, v), numeric(1)), na.rm = TRUE)

  injury_regions <- c(
    spine = as.integer(thoracic_fx == 1L || lumbar_fx == 1L || neural_any == 1L),
    head = max(get_yesno(row, "dx_tbi"), get_yesno(row, "dx_intracranial_hemorrhage_any"), na.rm = TRUE),
    thorax = max(get_yesno(row, "dx_thoracic_injury"), get_yesno(row, "dx_rib_fracture"), get_yesno(row, "dx_pneumothorax_hemothorax"), na.rm = TRUE),
    abdomen = get_yesno(row, "dx_abdominal_pelvic_injury"),
    upper = get_yesno(row, "dx_upper_extremity_injury"),
    lower = get_yesno(row, "dx_lower_extremity_injury")
  )
  region_count <- sum(injury_regions > 0, na.rm = TRUE)
  if ("dx_polyregion_injury_count" %in% vars) row$dx_polyregion_injury_count <- region_count
  if ("dx_polyregion_2plus" %in% vars) row$dx_polyregion_2plus <- as.integer(region_count >= 2)
  if ("dx_polyregion_3plus" %in% vars) row$dx_polyregion_3plus <- as.integer(region_count >= 3)
  if ("fracture_region_count" %in% vars) row$fracture_region_count <- sum(c(thoracic_fx, lumbar_fx, get_yesno(row, "dx_rib_fracture"), get_yesno(row, "dx_upper_extremity_injury"), get_yesno(row, "dx_lower_extremity_injury")) > 0, na.rm = TRUE)

  as.data.table(row)
}

prepare_model_data <- function(row, predictors) {
  predictors <- unique(as.character(predictors))
  for (v in setdiff(predictors, names(row))) row[, (v) := default_for(v)]
  x <- copy(row[, ..predictors])

  for (v in names(x)) {
    meta_row <- metadata[variable == v][1]
    choices <- if (nrow(meta_row) > 0) split_choices(meta_row$choices, character(0)) else character(0)
    if (length(choices) > 0 && !is_numeric_var(meta_row)) {
      x[[v]] <- factor(as.character(x[[v]]), levels = choices)
    } else if (is_yesno_var(meta_row) || is_numeric_var(meta_row)) {
      x[[v]] <- suppressWarnings(as.numeric(x[[v]]))
      x[[v]][!is.finite(x[[v]])] <- safe_numeric(default_for(v), 0)
    } else {
      x[[v]] <- as.character(x[[v]])
    }
  }

  x
}

make_sparse_matrix <- function(x, feature_names = NULL) {
  mm <- sparse.model.matrix(~ . - 1, data = as.data.frame(x))
  if (!is.null(feature_names)) {
    missing <- setdiff(feature_names, colnames(mm))
    if (length(missing) > 0) {
      zero <- Matrix(0, nrow = nrow(mm), ncol = length(missing), sparse = TRUE)
      colnames(zero) <- missing
      mm <- cbind(mm, zero)
    }
    extra <- setdiff(colnames(mm), feature_names)
    if (length(extra) > 0) mm <- mm[, setdiff(colnames(mm), extra), drop = FALSE]
    mm <- mm[, feature_names, drop = FALSE]
  }
  mm
}

predict_endpoint <- function(endpoint, row) {
  spec <- endpoint_specs[[endpoint]]
  obj <- get_endpoint_obj(endpoint)
  model <- get_model(obj)
  predictors <- get_predictors(endpoint, obj)
  feature_names <- get_feature_names(obj, model)
  x <- prepare_model_data(row, predictors)
  mm <- make_sparse_matrix(x, feature_names)
  pred <- predict(model, xgb.DMatrix(mm))

  if (spec$type == "multiclass") {
    levels <- obj$class_levels %||% obj$levels %||% meta_obj$discharge_levels %||% c("Home/home health", "Post-acute facility", "Death/hospice")
    pred <- as.numeric(pred)
    if (length(pred) != length(levels)) {
      pred <- pred[seq_len(min(length(pred), length(levels)))]
      levels <- levels[seq_along(pred)]
    }
    pred <- pred / sum(pred)
    return(data.table(endpoint = spec$label, outcome = levels, probability = pred))
  }

  p <- apply_binary_recalibration(as.numeric(pred[1]), obj)
  data.table(endpoint = spec$label, outcome = "Yes", probability = p)
}

fmt_prob <- function(p) percent(p, accuracy = 0.1)

risk_band <- function(p) {
  if (is.na(p)) return("Unavailable")
  if (p < 0.05) "Low"
  else if (p < 0.15) "Moderate"
  else if (p < 0.30) "Elevated"
  else "High"
}

