grouped_inputs <- function() {
  md <- metadata[is_visible_app == TRUE][order(group, app_order_num, label)]
  groups <- split(md, md$group)
  lapply(names(groups), function(g) {
    card(
      class = "input-card",
      card_header(g),
      card_body(lapply(seq_len(nrow(groups[[g]])), function(i) make_input(groups[[g]][i])))
    )
  })
}

