# ------------------------------------------------------------
# Server
# ------------------------------------------------------------

server <- function(input, output, session) {
  predictions <- eventReactive(input$predict, {
    row <- build_patient_row(input)
    endpoints <- if (identical(input$endpoint, "all")) available_endpoints else input$endpoint
    rbindlist(lapply(endpoints, function(ep) predict_endpoint(ep, row)), fill = TRUE)
  }, ignoreInit = FALSE)

  output$metric_cards <- renderUI({
    pred <- predictions()
    req(nrow(pred) > 0)

    if (input$endpoint == "discharge" || (input$endpoint == "all" && "discharge" %in% available_endpoints)) {
      discharge_rows <- pred[endpoint == endpoint_specs$discharge$label]
      if (nrow(discharge_rows) > 0) {
        top <- discharge_rows[which.max(probability)]
        main_cards <- list(
          div(class = "metric-card", div(class = "metric-value", fmt_prob(top$probability)), div(class = "metric-label", paste("Most likely disposition:", top$outcome)))
        )
      } else {
        main_cards <- list()
      }
    } else {
      main_cards <- list()
    }

    binary_rows <- pred[outcome == "Yes"]
    binary_cards <- lapply(seq_len(nrow(binary_rows)), function(i) {
      div(
        class = "metric-card",
        div(class = "metric-value", fmt_prob(binary_rows$probability[i])),
        div(class = "metric-label", binary_rows$endpoint[i]),
        div(class = "small-muted", paste("Risk band:", risk_band(binary_rows$probability[i])))
      )
    })

    div(class = "metric-grid", c(main_cards, binary_cards))
  })

  output$prediction_table <- renderTable({
    pred <- predictions()
    req(nrow(pred) > 0)
    out <- copy(pred)
    out[, Probability := fmt_prob(probability)]
    out[, `Risk band` := ifelse(outcome == "Yes", vapply(probability, risk_band, character(1)), "—")]
    setnames(out, c("endpoint", "outcome"), c("Endpoint", "Outcome"))
    out[, .(Endpoint, Outcome, Probability, `Risk band`)]
  }, striped = TRUE, bordered = FALSE, spacing = "m")
}

shinyApp(ui, server)
